async function aliyunDocumentCompletion(messages,maxTokens,analysis){
  const staged=[];
  try{
    const normalized=[];
    for(const message of messages){
      if(!Array.isArray(message.content)){normalized.push(message);continue}
      const content=[];
      for(const item of message.content){
        if(item?.type!=='file'||!item.file?.file_data?.startsWith('data:application/pdf;base64,')){content.push(item);continue}
        const bytes=Buffer.from(item.file.file_data.slice('data:application/pdf;base64,'.length),'base64');
        if(!bytes.length||bytes.subarray(0,5).toString()!=='%PDF-')throw Error('待分析文件不是有效 PDF。');
        const key='meeting-audio/document-analysis/'+randomUUID()+'.pdf';
        await aliyunOssPut(key,bytes,'application/pdf');staged.push(key);
        content.push({type:'file',file:{file_url:aliyunOssReadUrl(key,1),filename:item.file.filename||'meeting-material.pdf'}});
      }
      normalized.push({...message,content});
    }
    const result=await aliyunCompletion(normalized,maxTokens,documentAnalysisModel(),documentAnalysisFallbackModel());
    if(analysis){analysis.model=result.model;analysis.provider='阿里云百炼'}
    return result;
  }finally{
    for(const key of staged){try{await aliyunOssDelete(key)}catch(error){if(analysis){analysis.ossCleanupError=String(error.message||'PDF 暂存清理失败').slice(0,300);await save()}console.error('Qwen PDF 临时文件清理失败：',error.message)}}
  }
}
function yuntuApiHeaders(){const appCode=String(process.env.YUNTU_APIG_APPCODE||'').trim();if(!appCode)throw Error('尚未配置华为云市场 AppCode（YUNTU_APIG_APPCODE）。请在买家中心已购服务的 API 调用凭证中创建 AppCode。');return {'X-Apig-AppCode':appCode,accept:'application/json'}}
function yuntuApiUrl(value,label='接口'){let parsed;try{parsed=new URL(String(value||''))}catch{throw Error(`九云图${label}地址无效。`)}if(parsed.protocol!=='https:'||parsed.hostname!=='freem2.apistore.huaweicloud.com'||parsed.username||parsed.password)throw Error(`九云图${label}地址不符合预期，已拒绝访问。`);return parsed}
function findYuntuPdfUrl(value){
  const preferred=new Set(['pdf_url','pdfurl','download_url','downloadurl','file_url','fileurl','output_url','outputurl','result_url','resulturl']);
  const ignored=new Set(['document_url','documenturl','input_url','inputurl','query_url','queryurl']);
  const found=[];
  const visit=(node,parentKey='')=>{
    if(typeof node==='string'){
      const key=String(parentKey).toLowerCase();
      if(ignored.has(key)||!/^https:\/\//i.test(node))return;
      let parsed;try{parsed=new URL(node)}catch{return}
      if(parsed.protocol!=='https:'||parsed.username||parsed.password)return;
      const isPdf=/\.pdf(?:$|[?#])/i.test(parsed.pathname+parsed.search);
      if(preferred.has(key)||isPdf)found.push({url:node,preferred:preferred.has(key)});
      return;
    }
    if(Array.isArray(node)){for(const item of node)visit(item,parentKey);return;}
    if(node&&typeof node==='object')for(const [key,item] of Object.entries(node))visit(item,key);
  };
  visit(value);
  return found.sort((a,b)=>Number(b.preferred)-Number(a.preferred))[0]?.url||null;
}
