const onError=err=>{console.error(`服务启动失败（端口 ${port}）：${err.message}`);process.exitCode=1;};
const onListening=()=>{server.off('error',onError);console.log(`项目协作平台已启动：http://localhost:${port}（局域网设备请使用本机 IP 和端口 ${port}）`);};
function scanMeetingReminders(){const now=Date.now(),seen=new Set(database.notifications.map(n=>n.dedupeKey).filter(Boolean));let changed=false;for(const workspace of database.workspaces){if(workspace.project.status==='已归档')continue;for(const meeting of workspace.meetings||[]){if(meeting.status!=='待召开')continue;const start=Date.parse(`${meeting.date}T${meeting.start}:00+08:00`);if(!Number.isFinite(start)||start<=now)continue;const people=new Map();for(const person of workspace.people||[])people.set(person.id,person);const ids=new Set(meeting.attendeeIds||[]);for(const [id,name] of [[meeting.hostId,meeting.host],[meeting.organizerId,meeting.organizer]]){if(id)ids.add(id);else{const matches=(workspace.people||[]).filter(p=>p.name===name);if(matches.length===1)ids.add(matches[0].id)}}if(!meeting.attendeeIds?.length)for(const name of meeting.attendees||[]){const matches=(workspace.people||[]).filter(p=>p.name===name);if(matches.length===1)ids.add(matches[0].id)}const teamExtras=Array.isArray(meeting.teamReminderMinutes)?meeting.teamReminderMinutes:[];const prefs=database.meetingReminderPrefs.filter(x=>x.projectId===workspace.project.id&&x.meetingId===meeting.id);const minutesByUser=new Map();for(const id of ids)minutesByUser.set(id,new Set([20,...teamExtras]));for(const pref of prefs){if(ids.has(pref.userId)){const set=minutesByUser.get(pref.userId)||new Set([20,...teamExtras]);for(const minute of pref.minutes||[])set.add(minute);minutesByUser.set(pref.userId,set)}}for(const [userId,minutes] of minutesByUser){for(const minute of minutes){const trigger=start-Number(minute)*60000,lateDefault=Number(minute)===20&&trigger<=now-60000&&start>now;if(trigger>now||now-trigger>=60000&&!lateDefault)continue;const dedupeKey=`${workspace.project.id}:${meeting.id}:${userId}:${meeting.scheduleVersion||1}:${Number(minute)}`;if(seen.has(dedupeKey))continue;const person=people.get(userId);database.notifications.unshift({id:randomUUID(),dedupeKey,userId,projectId:workspace.project.id,meetingId:meeting.id,title:`会议提醒：${meeting.title}`,message:`会议将于${meeting.start}开始（${minute===1440?'提前1天':`提前${minute}分钟`}）。主持人：${meeting.host}。${meeting.format==='线上'?'线上链接':'地点'}：${meeting.location||'未填写'}。`,scheduledAt:new Date(trigger).toISOString(),createdAt:new Date().toISOString(),readAt:null,cancelledAt:null});seen.add(dedupeKey);changed=true}}}}if(database.notifications.length>2000){database.notifications.length=2000;changed=true}if(changed)void save().catch(error=>console.error('通知保存失败：',error))}
scanMeetingReminders();setInterval(scanMeetingReminders,15000).unref();
server.once('error',onError);server.once('listening',onListening);server.listen(port,host);
